int vf3_tenpp_leaf_adapter_contains(uint32_t pc) {
pc&=0x1fffffffu; unsigned lo=0,hi=sizeof(owned_pcs)/sizeof(owned_pcs[0]);
while(lo<hi) { unsigned mid=lo+(hi-lo)/2; if(owned_pcs[mid]<pc) lo=mid+1; else hi=mid; }
return lo<sizeof(owned_pcs)/sizeof(owned_pcs[0]) && owned_pcs[lo]==pc;
}
int vf3_tenpp_leaf_adapter(uint32_t entry,vf3_matrix_state*s,const vf3_ram_map*ram) {
if(!vf3_tenpp_leaf_adapter_contains(entry)) { s->failed_pc=entry; return 0; }
uint32_t pc=entry&0x1fffffffu;
if(pc<=0x0c058744u) return vf3_tenpp_leaf_adapter_0(entry,s,ram);
if(pc<=0x0c065a92u) return vf3_tenpp_leaf_adapter_1(entry,s,ram);
if(pc<=0x0c0c0420u) return vf3_tenpp_leaf_adapter_2(entry,s,ram);
if(pc<=0x0c0c9d1cu) return vf3_tenpp_leaf_adapter_3(entry,s,ram);
s->failed_pc=entry; return 0;
}
